mapper.select:
SELECT a.id, a.title, a.cover_url, a.summary, a.publish_time, a.view_count
FROM cms_article a
WHERE a.deleted = 0
  AND a.audit_status = 1
  AND a.project_id = #{projectId}
  AND a.id <> #{excludeId}
ORDER BY a.is_top DESC, a.publish_time DESC, a.id DESC
LIMIT #{limit}
